INSERT INTO public.custom_event_types VALUES ('284fee7b-1074-4165-b725-d208e68a3a13', 'confirmatorio', 'Ens. Confirmatório', '📘', true, 15, NULL, NULL, '2026-04-21 02:15:32.095517+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
