INSERT INTO public.devotional_responses VALUES ('f8bb4721-587b-40aa-af9f-96ad4867a04a', '7c675f6a-f519-4d74-b86e-eb3032a30c4a', '9bf5b69c-d399-4266-9e14-57570672ef33', 0, 'Se reder', '2026-05-13 19:55:04.678604+00', '2026-05-13 19:55:04.678604+00', NULL);
INSERT INTO public.devotional_responses VALUES ('0f001846-62da-4247-8e72-df4d6606657b', '7c675f6a-f519-4d74-b86e-eb3032a30c4a', '9bf5b69c-d399-4266-9e14-57570672ef33', 1, 'JESUSSSS', '2026-05-13 19:55:04.678604+00', '2026-05-13 19:55:04.678604+00', NULL);
INSERT INTO public.devotional_responses VALUES ('e31fcd96-7959-434d-a284-7fd132b35a4f', '7c675f6a-f519-4d74-b86e-eb3032a30c4a', '9bf5b69c-d399-4266-9e14-57570672ef33', 2, 'Poder ser reder', '2026-05-13 19:55:04.678604+00', '2026-05-13 19:55:04.678604+00', NULL);
INSERT INTO public.devotional_responses VALUES ('e0a92575-32e1-4838-babb-159d681f3c39', 'c703cab4-4562-496e-9243-fd6bd05d9a80', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 0, 'Ser nova criação é ter uma nova vida e identidade em Cristo.', '2026-05-15 00:15:45.507078+00', '2026-05-15 00:15:45.507078+00', NULL);
INSERT INTO public.devotional_responses VALUES ('184b1c3c-d208-4f9b-8751-2783ceb43fc6', 'c703cab4-4562-496e-9243-fd6bd05d9a80', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 1, 'Nosso passado não nos define porque Jesus nos perdoa e dá um novo começo.', '2026-05-15 00:15:45.507078+00', '2026-05-15 00:15:45.507078+00', NULL);
INSERT INTO public.devotional_responses VALUES ('dd538557-e85e-4592-8f0e-505c3a2c57fa', 'c703cab4-4562-496e-9243-fd6bd05d9a80', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 2, 'Cristo mudou nossa identidade, nos tornando filhos de Deus e perdoados.', '2026-05-15 00:15:45.507078+00', '2026-05-15 00:15:45.507078+00', NULL);
INSERT INTO public.devotional_responses VALUES ('04a814eb-ecc9-4307-bd07-1b25fd7d33ed', 'f3fe7c42-0110-42bd-831c-4ee0e5d3c1fc', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 0, 'Teste ', '2026-05-16 14:23:36.924239+00', '2026-05-16 14:23:36.924239+00', NULL);
INSERT INTO public.devotional_responses VALUES ('def13d75-424e-4707-a4fe-a75fd0c57254', 'f3fe7c42-0110-42bd-831c-4ee0e5d3c1fc', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 1, 'Teate', '2026-05-16 14:23:36.924239+00', '2026-05-16 14:23:36.924239+00', NULL);
INSERT INTO public.devotional_responses VALUES ('78605362-317f-4caa-835c-6efecee5ea43', 'f3fe7c42-0110-42bd-831c-4ee0e5d3c1fc', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 2, 'Yes ', '2026-05-16 14:23:36.924239+00', '2026-05-16 14:23:36.924239+00', NULL);
INSERT INTO public.devotional_responses VALUES ('4d28724c-33ca-4678-b8e3-d72daddd584f', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '4923904c-0624-414c-a226-c0e44bf04174', 0, 'Ser filho de Deus significa saber que Ele me ama, cuida de mim e nunca me abandona.', '2026-05-19 01:22:42.284937+00', '2026-05-19 01:22:42.284937+00', NULL);
INSERT INTO public.devotional_responses VALUES ('25bec106-3c00-4e7a-986b-97062e5b4034', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '4923904c-0624-414c-a226-c0e44bf04174', 1, 'Um pai ama, protege, ensina, ajuda e acompanha o filho em todos os momentos.', '2026-05-19 01:22:42.284937+00', '2026-05-19 01:22:42.284937+00', NULL);
INSERT INTO public.devotional_responses VALUES ('5a4c1ca7-48ca-414a-8fdb-07217105370a', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '4923904c-0624-414c-a226-c0e44bf04174', 2, 'Isso muda nossa relação com Deus porque passamos a confiar mais nEle e saber que nunca estamos sozinhos.', '2026-05-19 01:22:42.284937+00', '2026-05-19 01:22:42.284937+00', NULL);
INSERT INTO public.devotional_responses VALUES ('05434a0e-43fd-4c55-957a-0a37a5d61975', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '9bf5b69c-d399-4266-9e14-57570672ef33', 0, 'Significa tipo libertação ', '2026-05-13 20:47:23.071692+00', '2026-05-13 20:47:23.071692+00', NULL);
INSERT INTO public.devotional_responses VALUES ('912eee40-0c88-460c-9140-dda26d6326d5', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '9bf5b69c-d399-4266-9e14-57570672ef33', 1, 'Jesus', '2026-05-13 20:47:23.071692+00', '2026-05-13 20:47:23.071692+00', NULL);
INSERT INTO public.devotional_responses VALUES ('d8992dfc-e8ba-4b0c-bf6d-6abe1cfd6c0f', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '9bf5b69c-d399-4266-9e14-57570672ef33', 2, 'Viver com ele pertencendo a ele dar sua vida pra ele', '2026-05-13 20:47:23.071692+00', '2026-05-13 20:47:23.071692+00', NULL);
INSERT INTO public.devotional_responses VALUES ('0d08769b-77db-4500-b0ac-4609e465da39', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 0, 'Significa que Deus nos dá uma nova identidade e uma nova vida ', '2026-05-15 00:20:50.751584+00', '2026-05-15 00:20:50.751584+00', NULL);
INSERT INTO public.devotional_responses VALUES ('93cef754-38fd-4654-a5c0-c8ef7fe79815', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 1, 'Porque só o que nos define quem somos é o amor de Deus e a obra de Cristo ', '2026-05-15 00:20:50.751584+00', '2026-05-15 00:20:50.751584+00', NULL);
INSERT INTO public.devotional_responses VALUES ('b1ebe5fa-6393-4e27-a9a1-2217f7e478d3', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 2, 'Sim, antes vivíamos sem esperança e agora vivemos com esperança vivíamos culpados e agora vivemos perdoados', '2026-05-15 00:20:50.751584+00', '2026-05-15 00:20:50.751584+00', NULL);
INSERT INTO public.devotional_responses VALUES ('794134d3-0029-49a7-8238-ba0a3d98a078', 'aa7cfdb6-13b7-4988-8922-86de735eeab2', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 0, 'Significa que Deus nos ama.', '2026-05-16 15:25:18.000716+00', '2026-05-16 15:25:18.000716+00', NULL);
INSERT INTO public.devotional_responses VALUES ('d284ded6-327e-4e56-81c9-95230b86b40a', 'aa7cfdb6-13b7-4988-8922-86de735eeab2', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 1, 'Pois nós só podemos encontrar a salvação por meio de Jesus.', '2026-05-16 15:25:18.000716+00', '2026-05-16 15:25:18.000716+00', NULL);
INSERT INTO public.devotional_responses VALUES ('fe3fe0a1-9666-48be-8055-b9458e60190b', 'aa7cfdb6-13b7-4988-8922-86de735eeab2', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 2, 'Traz descanso não preciso provar meu valor pra ninguém.', '2026-05-16 15:25:18.000716+00', '2026-05-16 15:25:18.000716+00', NULL);
INSERT INTO public.devotional_responses VALUES ('39cf712e-9b82-4776-8dc1-6ca16140db2a', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '4923904c-0624-414c-a226-c0e44bf04174', 0, 'Nunca ficar sozinho que ele cuida de nossa vida e nossa vida tem valor e propósito ', '2026-05-19 01:56:38.335175+00', '2026-05-19 01:56:38.335175+00', NULL);
INSERT INTO public.devotional_responses VALUES ('1c59c5a1-aeb1-417a-af60-893062505c8f', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '4923904c-0624-414c-a226-c0e44bf04174', 1, 'Cuida e acolhe', '2026-05-19 01:56:38.335175+00', '2026-05-19 01:56:38.335175+00', NULL);
INSERT INTO public.devotional_responses VALUES ('19d88bd9-37d1-472c-901a-fb12618d0168', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '4923904c-0624-414c-a226-c0e44bf04174', 2, 'Que Deus é uma das maiores coisas que a bíblia fala sobre nós.isso significa que Deus não é apenas um Deus distante,mas um Pai que nos ama, cuida de nós,perdoa e nos acompanha ', '2026-05-19 01:56:38.335175+00', '2026-05-19 01:56:38.335175+00', NULL);
INSERT INTO public.devotional_responses VALUES ('cd54b0c2-f271-4179-85ca-0d951483e920', '7640c7e4-6780-4c27-8a04-ae5ab375f580', '9bf5b69c-d399-4266-9e14-57570672ef33', 0, 'A palavra redenção significa resgatar, libertar, comprar de volta.', '2026-05-13 20:51:55.957922+00', '2026-05-13 20:51:55.957922+00', NULL);
INSERT INTO public.devotional_responses VALUES ('b6e2f28d-9b73-4a16-8f7d-26a06c11741d', '7640c7e4-6780-4c27-8a04-ae5ab375f580', '9bf5b69c-d399-4266-9e14-57570672ef33', 1, 'Nós éramos escravos do pecado, mas Jesus pagou o preço com sua própria vida na cruz para nos libertar.', '2026-05-13 20:51:55.957922+00', '2026-05-13 20:51:55.957922+00', NULL);
INSERT INTO public.devotional_responses VALUES ('39098991-3b71-4ef7-bc9c-399c7f02ac84', '7640c7e4-6780-4c27-8a04-ae5ab375f580', '9bf5b69c-d399-4266-9e14-57570672ef33', 2, 'Viver sabendo que foi ele que nos salvou do pecado .
INSERT INTO public.devotional_responses VALUES ('09ee5a7b-aee5-4442-9819-9cea7b05ede1', '7640c7e4-6780-4c27-8a04-ae5ab375f580', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 0, 'isso não significa que a pessoa nunca mais vai errar ou que tudo muda de um dia para o outro', '2026-05-15 00:30:47.156441+00', '2026-05-15 00:30:47.156441+00', NULL);
INSERT INTO public.devotional_responses VALUES ('d32b51c8-2255-46e5-8d68-e05438776ff3', '7640c7e4-6780-4c27-8a04-ae5ab375f580', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 1, 'Ser nova criação significa que nossa história não é definida pelo nosso passado, mas por aquilo que Cristo fez por nós. ', '2026-05-15 00:30:47.156441+00', '2026-05-15 00:30:47.156441+00', NULL);
INSERT INTO public.devotional_responses VALUES ('23c1c969-90a4-47cd-8936-82ee1aa0d202', '7640c7e4-6780-4c27-8a04-ae5ab375f580', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 2, 'Que nos somos perdoados ', '2026-05-15 00:30:47.156441+00', '2026-05-15 00:30:47.156441+00', NULL);
