INSERT INTO public.devotional_responses VALUES ('4f933834-d23e-4797-8436-4fa21c1022a6', 'c703cab4-4562-496e-9243-fd6bd05d9a80', '4923904c-0624-414c-a226-c0e44bf04174', 0, 'Ser filha de Deus,  é ser amada e cuidada por ele .', '2026-05-18 21:18:25.613356+00', '2026-05-18 21:18:25.613356+00', NULL);
INSERT INTO public.devotional_responses VALUES ('bda4e5d7-6cf2-4f15-88ba-132d101e7b2a', 'c703cab4-4562-496e-9243-fd6bd05d9a80', '4923904c-0624-414c-a226-c0e44bf04174', 1, 'Um pai ama, protege e cuida do filho ', '2026-05-18 21:18:25.613356+00', '2026-05-18 21:18:25.613356+00', NULL);
INSERT INTO public.devotional_responses VALUES ('a4f17305-5725-4b73-8635-9f012b4c35ff', 'c703cab4-4562-496e-9243-fd6bd05d9a80', '4923904c-0624-414c-a226-c0e44bf04174', 2, 'Isso nos faz confiar mais em Deus como pai .', '2026-05-18 21:18:25.613356+00', '2026-05-18 21:18:25.613356+00', NULL);
INSERT INTO public.devotional_responses VALUES ('bf275970-7d49-47d7-8504-824101995b37', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 0, 'Ser nova criação significa ter uma vida transformada por Cristo, deixando para trás os erros do passado e vivendo de uma forma melhor.', '2026-05-14 03:34:53.743797+00', '2026-05-14 03:34:53.743797+00', NULL);
INSERT INTO public.devotional_responses VALUES ('084b1200-0944-4fec-887e-de11ab1064c0', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 1, 'Nosso passado não define quem somos porque Deus nos dá uma nova chance e nos vê com amor e perdão.', '2026-05-14 03:34:53.743797+00', '2026-05-14 03:34:53.743797+00', NULL);
INSERT INTO public.devotional_responses VALUES ('3445783b-3cc9-4f2b-9331-fec89c60fe12', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 2, 'Cristo muda nossa identidade porque, através do Seu amor e sacrifício, passamos a ser filhos de Deus e uma nova criação.', '2026-05-14 03:34:53.743797+00', '2026-05-14 03:34:53.743797+00', NULL);
