INSERT INTO public.devotional_responses VALUES ('374df975-eead-4b44-be05-1c69aa7ec639', '7640c7e4-6780-4c27-8a04-ae5ab375f580', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 1, 'Por que precisamos de Deus ', '2026-05-15 22:36:02.506275+00', '2026-05-15 22:36:02.506275+00', NULL);
INSERT INTO public.devotional_responses VALUES ('24f51a33-ecfb-49c5-9194-5a1e9c4c0eb5', '7640c7e4-6780-4c27-8a04-ae5ab375f580', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 2, 'Que assim sabemos que Deus nos ama do jeito que somos.
