INSERT INTO public.devotional_responses VALUES ('a5d5e97f-b3c6-4926-9eb4-f7ad60887d26', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '4923904c-0624-414c-a226-c0e44bf04174', 2, 'Muda saber que Deus deu seu filho para nós salvar, e isso significa que nós temos uma longa vida pra viver, muitas conquistas para conquistar.', '2026-05-18 21:57:34.134131+00', '2026-05-18 21:57:34.134131+00', NULL);
