INSERT INTO public.devotional_responses VALUES ('7481ee91-ecef-4fd0-8901-51988c78093a', '9289d1ce-a632-4cd7-930e-73023e549ec5', '4923904c-0624-414c-a226-c0e44bf04174', 0, 'Nunca estar sozinho,ter uma pessoa de confiança que te ama pelo que você é, não o que faz', '2026-05-18 22:24:36.943219+00', '2026-05-18 22:24:36.943219+00', NULL);
