INSERT INTO public.devotional_responses VALUES ('2eff539c-3f6f-42a4-bbcf-df190f990cd2', '9289d1ce-a632-4cd7-930e-73023e549ec5', '4923904c-0624-414c-a226-c0e44bf04174', 2, 'Que Deus não é uma autoridade que você tem medo,mas uma pessoa próxima como um pai mesmo que você conversa e vive junto', '2026-05-18 22:24:36.943219+00', '2026-05-18 22:24:36.943219+00', NULL);
INSERT INTO public.devotional_responses VALUES ('cb12ee97-f734-4b94-b0c4-6a4fd97d3f80', '9289d1ce-a632-4cd7-930e-73023e549ec5', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 0, 'É ser uma nova pessoa,com pensamentos e valores diferentes', '2026-05-14 21:30:50.410279+00', '2026-05-14 21:30:50.410279+00', NULL);
INSERT INTO public.devotional_responses VALUES ('4bc0cea2-b745-40d7-b2a5-29fda436fd4c', '9289d1ce-a632-4cd7-930e-73023e549ec5', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 1, 'Pois o que nos define é ser a criação de Deus,e pertencer a Ele', '2026-05-14 21:30:50.410279+00', '2026-05-14 21:30:50.410279+00', NULL);
INSERT INTO public.devotional_responses VALUES ('709d4c4b-be74-4192-9a2f-276f6822b328', '9289d1ce-a632-4cd7-930e-73023e549ec5', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 2, 'Agora somos perdoados,temos esperança, fé,respeito e educação pelos outros', '2026-05-14 21:30:50.410279+00', '2026-05-14 21:30:50.410279+00', NULL);
