INSERT INTO public.devotional_responses VALUES ('7f98a073-d4f1-4e7f-89ff-e10f6c440660', '914b898d-24a3-46ad-a764-d2f24e5115d1', '4923904c-0624-414c-a226-c0e44bf04174', 2, 'Saber que estamos protegidos ', '2026-05-18 23:07:31.756506+00', '2026-05-18 23:07:31.756506+00', NULL);
INSERT INTO public.devotional_responses VALUES ('0c35db6d-a61e-435c-ae0e-42d602f0d50d', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 0, 'Significa que nossa história não é formada pelos erros do passado, e sim por o que Jesus fez por nós, nossos pecados não define quem nós somos.', '2026-05-14 22:50:59.678418+00', '2026-05-14 22:50:59.678418+00', NULL);
INSERT INTO public.devotional_responses VALUES ('fde2aa10-4e3e-47c7-96a8-f7792ad72031', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 1, 'Porque Deus veio e restaurou todos nossos erros e pecados, e isso faz refletir de como podemos ter cada vez mais esperança, e os nossos erros, não podem definir todos, e sim o nossos caráter.', '2026-05-14 22:50:59.678418+00', '2026-05-14 22:50:59.678418+00', NULL);
INSERT INTO public.devotional_responses VALUES ('dc84ed56-5455-4e9f-af0e-3d1194d9d0ee', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 2, 'Mudou a forma como nós vemos o mundo, tendo mais esperança, crendo mais em Deus, tentando não cometer muitos erros.', '2026-05-14 22:50:59.678418+00', '2026-05-14 22:50:59.678418+00', NULL);
INSERT INTO public.devotional_responses VALUES ('83f98a68-0821-42d0-91f3-99b87acbff35', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 0, 'Isso significa, que Deus ama todos, perdoa-os pelos pecados, e ele não salva porque nós somos bons, e sim porque ele é.', '2026-05-16 01:15:16.090203+00', '2026-05-16 01:15:16.090203+00', NULL);
INSERT INTO public.devotional_responses VALUES ('92508a82-893a-44bb-acae-4353fdd672f0', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 1, 'Porque o pecado nos separa de Deus e nenhum esforço, obra ou dinheiro humano é capaz de pagar o preço por nossas falhas.', '2026-05-16 01:15:16.090203+00', '2026-05-16 01:15:16.090203+00', NULL);
INSERT INTO public.devotional_responses VALUES ('6f40c7a9-96a2-4337-a57b-7e51b9fbbd34', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '3d64d377-9892-4d7d-a17c-aaf074fe9de6', 2, 'muda tudo, pois substitui a ansiedade de tentar "merecer" o amor divino por uma paz profunda e transformadora.', '2026-05-16 01:15:16.090203+00', '2026-05-16 01:15:16.090203+00', NULL);
