INSERT INTO public.devotional_responses VALUES ('934800a5-e71f-4bdf-8c5a-c9ed23a08bf9', 'c703cab4-4562-496e-9243-fd6bd05d9a80', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 0, 'Às vezes sinto medo, mas lembro que Deus me aceita pela graça, não pelos meus erros.', '2026-04-08 17:27:15.59439+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('5cb7c8c5-701b-42c7-9dc5-8eac2397d8e7', 'c703cab4-4562-496e-9243-fd6bd05d9a80', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 1, 'Isso me traz paz, pois sei que Cristo já pagou por tudo e não preciso viver na culpa.', '2026-04-08 17:27:15.59439+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('e597e7b1-fe18-4c2b-9948-d62d573af76c', '32a9f112-1192-4b2a-918f-c2895a76ade3', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 0, 'Não', '2026-04-08 18:19:48.469589+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
