INSERT INTO public.devotional_responses VALUES ('bb36ec8d-3bf3-440e-abc5-59597dfcad88', '2f773751-38c2-45a1-8ee0-f5b856092730', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 0, 'Não! Sei que sou profundamente amado por Deus!
INSERT INTO public.devotional_responses VALUES ('c7287760-c8b5-4a10-952a-c78042b9f8e1', '2f773751-38c2-45a1-8ee0-f5b856092730', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 1, 'Saber que não há condenação, me faz viver sem medo de Deus me castigar e livre para tentar viver e acertar e mesmo que eu errar não serei castigado.', '2026-04-08 19:28:54.818785+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('49361a19-d4be-4d99-b1ab-09c2152b4d6c', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 0, 'Não, pois eu fui criado crendo nele, e sei que sou digno da minha vida, e todos tem um propósito especial de Cristo.', '2026-04-08 21:37:06.741818+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('fb35d559-cb1e-4df7-b829-a582119606f6', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 1, 'Traz segurança sabendo que Deus tem um propósito pra mim e um futuro lindo, e sempre passo a ter alívio quando penso que Deus sabe e guarda meu futuro.', '2026-04-08 21:37:06.741818+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('0b192205-37fa-49ec-96ad-555eee3b628f', '9289d1ce-a632-4cd7-930e-73023e549ec5', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 0, 'Sim,porque as vezes acabo pecando', '2026-04-08 21:41:33.421898+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('a900bc61-23b0-4be4-ae4a-3598c028e438', '9289d1ce-a632-4cd7-930e-73023e549ec5', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 1, 'Porque Cristo perdoa os que erram,e isso significa que não precisa ser perfeito,que alguma hora vamos acabar pecando,mas com Cristo, não há condenação,e sim graça,e confiar que Ele já foi pago na cruz por nós', '2026-04-08 21:41:33.421898+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('af482809-1eed-4512-ae11-0aee1de6ba40', '66b31cf2-7782-4253-98ea-3b6d631703a4', 'd1f46ea0-fa0d-43d1-9f1a-b0cf522d17af', 0, 'Identidade ', '2026-04-08 22:10:48.832943+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
