INSERT INTO public.devotional_responses VALUES ('fada45d7-facf-4309-bb2b-a16d1581543b', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 0, 'Sim', '2026-04-08 22:14:29.510299+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
