INSERT INTO public.devotional_responses VALUES ('a97bb4ef-89a6-4573-9262-dfa504afb94f', '7640c7e4-6780-4c27-8a04-ae5ab375f580', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 0, 'Não ', '2026-04-08 22:14:43.141972+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('636f1734-31d3-48a9-86f4-7682bff83017', '7640c7e4-6780-4c27-8a04-ae5ab375f580', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 1, 'Que ele me ama do jeito que sou ', '2026-04-08 22:14:43.141972+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('8068a789-a0d3-435f-8f75-2ddfcf745b2a', 'ebea6be2-1d97-4b43-a5bc-8f92af388061', 'ba0f8dfe-02e3-4c8a-8bfc-16a9ce1afde9', 0, 'Sim ', '2026-04-08 22:17:12.434272+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
