INSERT INTO public.devotional_responses VALUES ('1fe68476-63cb-44c5-bb44-c594b426fc45', '70a2c6f1-f740-4669-b8dc-29b38f04d9d9', 'e3645858-1004-4f31-8d73-708e1749c4bd', 1, 'Que o nosso valor já foi provado. ', '2026-04-11 15:29:37.528971+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('2872fd5b-3369-40da-a26d-8ea37892b5e2', '70a2c6f1-f740-4669-b8dc-29b38f04d9d9', 'e3645858-1004-4f31-8d73-708e1749c4bd', 2, 'Não precisamos provar nada a ninguém, em Cristo já somos amados.', '2026-04-11 15:29:37.528971+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('dfed19f0-bc88-4723-b53b-46af44a474ca', '70a2c6f1-f740-4669-b8dc-29b38f04d9d9', 'd1f46ea0-fa0d-43d1-9f1a-b0cf522d17af', 0, 'Identidade.', '2026-04-11 15:35:37.169971+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
