INSERT INTO public.devotional_responses VALUES ('60176305-0aa4-4592-973b-282fd502c2fb', '70a2c6f1-f740-4669-b8dc-29b38f04d9d9', 'a2b6f9a0-d031-4841-871b-280512b684eb', 0, 'Que Deus nos tira das trevas e mostra a sua luz.', '2026-04-11 15:39:09.375127+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
