INSERT INTO public.devotional_responses VALUES ('3dcd6a66-d279-491d-a2e9-f37026915cff', '985bc110-c90a-4762-8b1b-7b081e0c6863', '6cb1c7b2-9946-4bb3-bda2-d4715e2ce7ad', 1, 'Com seu grande amor', '2026-04-11 16:03:41.794889+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
