INSERT INTO public.devotional_responses VALUES ('790d50b1-5053-4c94-953d-c042a99599f8', '985bc110-c90a-4762-8b1b-7b081e0c6863', '2e26fe88-3337-4504-a083-c448326f0210', 1, 'Ser uma pessoa nova, diferente', '2026-04-11 16:07:54.682232+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
