INSERT INTO public.devotional_responses VALUES ('a36af4c3-7238-4e6d-8ffa-af4f0714b495', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '534f7bd1-d3ce-4cf0-888d-87951209aba1', 0, 'Sim', '2026-04-11 16:12:56.19546+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
