INSERT INTO public.devotional_responses VALUES ('bbfbc86d-04a8-44d8-bcc1-30fdfa19e27c', 'd92c04c7-9f6b-4093-ac69-7bdc4ad82f13', '534f7bd1-d3ce-4cf0-888d-87951209aba1', 0, 'Sim ', '2026-04-11 18:32:33.118706+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('c03e7b13-3737-49cd-8c86-ad8d42b8f152', 'd92c04c7-9f6b-4093-ac69-7bdc4ad82f13', '534f7bd1-d3ce-4cf0-888d-87951209aba1', 1, 'Muda que eu sou o templo do Espírito Santo ', '2026-04-11 18:32:33.118706+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('0e669db0-d415-4305-9a5b-25d97d56a7d5', '985bc110-c90a-4762-8b1b-7b081e0c6863', 'af72e9fc-4ffc-4ecc-9fe4-732e059f947e', 0, 'Que ele é o filho de Deus, o salvador', '2026-04-12 11:23:49.749397+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('8d8a0e4f-38e7-4df6-b2e5-f3a63c082249', '985bc110-c90a-4762-8b1b-7b081e0c6863', 'af72e9fc-4ffc-4ecc-9fe4-732e059f947e', 1, 'Atualmente, vem de mim. Mas muitas vezes apenas repetia o que havia aprendido.', '2026-04-12 11:23:49.749397+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('b01c0049-296d-4633-bc92-a1502300d38e', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 0, 'Nas sua notas, aparência, trabalho ou sua popularidade.', '2026-04-12 14:30:32.686995+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('bb17d382-288d-4d27-8e0f-7226ac5bd74f', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 1, 'Nossa indentidade principal não está no que fazemos mas em quem somos diante de Deus.', '2026-04-12 14:30:32.686995+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('d2b80641-594a-4c72-8207-1b3f32a0e551', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 2, 'Muda a forma como vemos a vida, porque não vivemos mais tentando ser aceitos, mas vivemos porque já fomos aceitos por Deus ', '2026-04-12 14:30:32.686995+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('dcc578b5-f42c-46b2-bada-48858b6cf574', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', 'd860c7de-47c9-4665-bf9d-315cd5cd4e6f', 0, 'Sempre que Deus me criou e cada um tem a sua importância ', '2026-04-12 16:46:24.443125+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('289d7389-efd8-4a10-a644-43fc11426c40', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', 'd860c7de-47c9-4665-bf9d-315cd5cd4e6f', 1, 'Que Deus me criou para eu refletir alguma coisa sobre ele', '2026-04-12 16:46:24.443125+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('9acb6007-5bb0-4035-9832-beec1e91601c', '66b31cf2-7782-4253-98ea-3b6d631703a4', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 0, 'Com outras pessoas ', '2026-04-12 17:14:27.228349+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('ff00a880-a9f0-454d-b1da-380c0818b8ae', '66b31cf2-7782-4253-98ea-3b6d631703a4', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 1, 'Por que as opiniões podem mudar ', '2026-04-12 17:14:27.228349+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('ff25595a-fcdd-4dd2-aa4d-3ea753aefb1a', '66b31cf2-7782-4253-98ea-3b6d631703a4', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 2, 'Não procurar a opinião dos outros pq em Deus já somos aceitos ', '2026-04-12 17:14:27.228349+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('4e21614b-d799-4166-a07a-f7b7ab5111d1', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '5e859f9e-3016-4482-96fd-1cae2e76f966', 0, 'Viver longe de Deus, confiar mais em nós mesmos do que nele e tentar viver sem ele.', '2026-04-14 00:15:16.131822+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('591305d4-fb15-468e-adb9-6834fb5e9e77', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '5e859f9e-3016-4482-96fd-1cae2e76f966', 1, 'O pecado afetou não só nossas atitudes, mas também nossa indentidade. Em vez de vivermos como filhos que confiam em Deus, passamos a viver com medo, culpa, comparação e orgulho.', '2026-04-14 00:15:16.131822+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('2508374e-0263-4f8a-8b3f-f9567905c289', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '5e859f9e-3016-4482-96fd-1cae2e76f966', 2, 'A Bíblia diz que todos pecaram. Isso significa que todos nós falhamos, erramos e nos afastamos de Deus ', '2026-04-14 00:15:16.131822+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('72cb18ee-b3d8-40ba-8d27-56b29d55e304', 'af8a49dd-780a-419f-b967-a9c9e4b5837c', 'e3645858-1004-4f31-8d73-708e1749c4bd', 0, 'Para serem aceitas e mais populares ou amadas', '2026-04-14 00:34:51.829851+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('62278571-907b-4c00-8e89-48c3bee6c177', 'af8a49dd-780a-419f-b967-a9c9e4b5837c', 'e3645858-1004-4f31-8d73-708e1749c4bd', 1, 'Na cruz mostra que o nosso valor ja foi provado. Jesus morreu por nós quando ainda éramos pecadores ', '2026-04-14 00:34:51.829851+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('151db414-edef-4769-b0d9-739060ea9e1c', 'af8a49dd-780a-419f-b967-a9c9e4b5837c', 'e3645858-1004-4f31-8d73-708e1749c4bd', 2, 'Saber que ja somos amados pelo ser mais importante ', '2026-04-14 00:34:51.829851+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('a323c5a2-bfc9-4ae4-ad9f-f31ae980ee68', 'ba6442c9-bc68-4670-a14f-bc7f7225fb93', '534f7bd1-d3ce-4cf0-888d-87951209aba1', 0, 'Sim', '2026-04-14 00:59:42.690073+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('9f7f9097-8ad7-40d0-9262-2a567b7044fc', 'ba6442c9-bc68-4670-a14f-bc7f7225fb93', '534f7bd1-d3ce-4cf0-888d-87951209aba1', 1, 'Ter uma vida saudável não se drogar não machucar o próprio corpo', '2026-04-14 00:59:42.690073+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('3883a9ce-fcb7-433d-87ff-c5655b6a650b', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', 'e6008830-87f7-4b01-865f-30595ccb5a7d', 0, 'Tento me indentificar como filho de Deus então sim ', '2026-04-14 14:48:29.676339+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('ae12f069-9cd0-4b0c-9829-018ccc6fae43', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', 'e6008830-87f7-4b01-865f-30595ccb5a7d', 1, 'Bom pq deus da um propósito para cada im', '2026-04-14 14:48:29.676339+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('7a29bc5e-5e4b-434a-9cd4-437f4f314169', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '9bf5b69c-d399-4266-9e14-57570672ef33', 0, 'A palavra redenção significa resgatar e libertar
INSERT INTO public.devotional_responses VALUES ('8f80decf-2746-4754-9def-8edf7c11874b', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '9bf5b69c-d399-4266-9e14-57570672ef33', 1, 'Jesus ele libertou a gente da morte da cruz ele morreu por a gente', '2026-04-14 14:54:06.948334+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('19ee80f9-5123-4dac-82b5-232fa83d4b94', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '9bf5b69c-d399-4266-9e14-57570672ef33', 2, 'Gratidão porque ele que salvou a gente ', '2026-04-14 14:54:06.948334+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('6855a635-ec79-4929-9c14-b5472cbb3332', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '9bf5b69c-d399-4266-9e14-57570672ef33', 0, 'Redenção significa resgatar, libertar, comprar de volta. ', '2026-04-14 21:34:13.25581+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('7e01a85f-f80c-4496-bda3-04357c264caa', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '9bf5b69c-d399-4266-9e14-57570672ef33', 1, 'Jesus pagou preço com sua própria vida na cruz para nos lebertar.', '2026-04-14 21:34:13.25581+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('a946ba77-2272-4d09-977d-2b4de62ddd4c', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '9bf5b69c-d399-4266-9e14-57570672ef33', 2, 'É viver sabendo que fomos resgatados por Jesus e agora pertencemos a ele.', '2026-04-14 21:34:13.25581+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('73e32ef4-8bbb-4ff4-8d29-ee2e1cc0e381', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 0, 'Nova criação significa uma nova vida', '2026-04-15 23:35:31.880174+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('a44cf2d8-32d1-41b4-90ce-00cf71f7dfa4', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 1, 'Nosso passado na define quem por que deus nos da u.a nova o dentidade', '2026-04-15 23:35:31.880174+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('ed03a633-84e8-4757-9740-c78c3ef33e37', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 2, 'Ele perdoa nossos pecados ', '2026-04-15 23:35:31.880174+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('bbc58e2b-a18f-45fd-a5c5-d10bd8778fb9', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 0, 'Não significa que a pessoa nunca mais vai errar o que tudo muda de um dia para o outro.', '2026-04-16 01:49:41.23023+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('7d2bd93f-66b7-4084-88a0-f855840f5809', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 1, 'Porque antes vivíamos longe de Deus, agora pertencemos a ele.', '2026-04-16 01:49:41.23023+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('984eef4a-55e0-4d32-a7af-1a7dd4f89fa5', '84f87cda-6f3a-43ef-a265-93e7c3d15c23', '4f5849b5-6c11-456a-85e5-40d90b26b4ed', 2, 'Nos perdoando dos pecados.', '2026-04-16 01:49:41.23023+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('1e523e37-4675-467d-b838-83ab5e883aa9', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '4923904c-0624-414c-a226-c0e44bf04174', 0, 'Significa que nos temos um pai que cuida de nós ', '2026-04-17 17:27:57.198586+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('56192731-bc33-433f-8cf6-0e1bb91752eb', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '4923904c-0624-414c-a226-c0e44bf04174', 1, 'Cuida', '2026-04-17 17:27:57.198586+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('69cfd68b-ed12-42d0-bec3-7be4e006ee63', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '4923904c-0624-414c-a226-c0e44bf04174', 2, 'Que a gente tem mais fé se aproxima de Deus ', '2026-04-17 17:27:57.198586+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('eb898eac-83b3-428c-84c3-a73e3ce20411', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '12f627ce-ad3a-45d1-b90a-6282070e9524', 0, 'Estão bem, tenho muitos amigos', '2026-04-17 22:02:38.314854+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('e0adaab6-27c2-4b44-b209-23cd3436e9fa', '7c2a671d-0f04-463e-ab89-d0e4fae6d165', '12f627ce-ad3a-45d1-b90a-6282070e9524', 1, 'Sim todos os dias', '2026-04-17 22:02:38.314854+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('8c0535c3-e460-4604-9b10-aecaf409ae5d', '8bf335ab-907e-497b-b08b-615ad716e722', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 0, 'Nas coisas temporárias da vida , como a sua aparência e popularidade ', '2026-04-17 22:08:48.940948+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('8de999ff-0703-4663-9bb0-8d14c3c572bd', '8bf335ab-907e-497b-b08b-615ad716e722', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 1, 'Porque nossa indentidade é recebida de Deus e não formada por coisas temporárias ', '2026-04-17 22:08:48.940948+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
