INSERT INTO public.devotional_responses VALUES ('0d3dd2c5-8091-448c-bf1b-6f88b73aa000', 'd1157e70-4aa7-4e5c-8b78-4fbb2294702a', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Quando eu peso para ele me ajudar em alguma coisa e ele deixa que eu faça ', '2026-04-22 10:23:10.502052+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('277f92e5-cba2-41a1-a84d-c0769846b5cc', '985bc110-c90a-4762-8b1b-7b081e0c6863', '33c931a8-3267-4d0f-90e8-229c9b56fd39', 0, 'Além de entender que ele sofreu dores quando se fez carne, é ter a certeza que ele compreende exatamente meus sentimentos, lutas e aflições ', '2026-04-21 02:29:14.154809+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('52136e00-bd4a-4836-a0d1-77bd9f5acfc4', '985bc110-c90a-4762-8b1b-7b081e0c6863', '33c931a8-3267-4d0f-90e8-229c9b56fd39', 1, 'Sim. Isto alivia as lutas, batalhas e dores.', '2026-04-21 02:29:14.154809+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
