INSERT INTO public.devotional_responses VALUES ('1f02a2fb-1e84-4833-bfbb-bead44a88e6e', '985bc110-c90a-4762-8b1b-7b081e0c6863', '6c37261b-db87-4224-b42f-546e9d6b8f2f', 0, 'Sim. Se Ele é o caminho, posso confiar nisso.', '2026-04-22 13:40:09.524884+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('0b1eae46-3a55-495d-82b9-6ce31abd4124', '985bc110-c90a-4762-8b1b-7b081e0c6863', '6c37261b-db87-4224-b42f-546e9d6b8f2f', 1, 'Às vezes tento fazer isso. Mas lembro do Senhor, do criador, e procuro voltar a confiar nele como sendo o único caminho.', '2026-04-22 13:40:09.524884+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('05fc0fa9-f839-4cf7-8b00-b5847a3b9dac', '985bc110-c90a-4762-8b1b-7b081e0c6863', '2bc9be13-ca22-4f97-a054-0822e279b99b', 0, 'Às vezes esta ideia de merecer a salvação vem à tona. Então, preciso lembrar do sangue derramado na cruz, de como não sou merecedora, mas como Cristo me ama.', '2026-04-22 13:41:59.736244+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('a889e039-8a01-44d9-afd5-a514cb2f43e9', '985bc110-c90a-4762-8b1b-7b081e0c6863', '2bc9be13-ca22-4f97-a054-0822e279b99b', 1, 'Traz paz.', '2026-04-22 13:41:59.736244+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('2f98f3e1-ce90-491f-8880-1ee4146ba806', '985bc110-c90a-4762-8b1b-7b081e0c6863', '33212d42-ccc1-4887-891d-80c7a46207eb', 0, 'Meu futuro, minhas inseguranças em relação a ele.', '2026-04-22 13:43:18.375716+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('ed56f890-eaa9-4f9b-8056-4bc10f8fa5b6', '985bc110-c90a-4762-8b1b-7b081e0c6863', '33212d42-ccc1-4887-891d-80c7a46207eb', 1, 'Sim. Mas preciso fazer isso constantemente', '2026-04-22 13:43:18.375716+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('1fb9100b-78d2-4df6-87dd-76da92a3c847', '7c675f6a-f519-4d74-b86e-eb3032a30c4a', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Porque criar uma dúvida pode causar, desconfiança, aliás imagina desconfiar do salvador!', '2026-04-22 15:04:18.193363+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('722415ec-c44a-4672-9832-175064b800f6', '7c675f6a-f519-4d74-b86e-eb3032a30c4a', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Nós momentos mais críticos,tipo doença sem cura,quando alguém que amamos adoece....etc', '2026-04-22 15:04:18.193363+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('dce910d2-adeb-4b00-93ed-cc4d481998e6', '9b42238e-4e16-4511-9073-5281a0b6b1f4', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Para pensarmos melhor', '2026-04-22 15:04:23.181727+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('e0fbf494-bf6b-4d7f-9c26-96248db039eb', '9b42238e-4e16-4511-9073-5281a0b6b1f4', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Em nenhum ue', '2026-04-22 15:04:23.181727+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('f8d131fb-fd28-45af-b40f-c20b2256a6ed', '32a9f112-1192-4b2a-918f-c2895a76ade3', '7d433010-74aa-4b63-bbca-c1db37c6ab21', 0, 'A poluição', '2026-04-22 15:51:48.617793+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('e141a169-7298-4fa8-b37b-9a4a5c857304', '32a9f112-1192-4b2a-918f-c2895a76ade3', '7d433010-74aa-4b63-bbca-c1db37c6ab21', 1, 'Pois sempre pecamos', '2026-04-22 15:51:48.617793+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('6d08b67b-80a1-46a3-a076-ab8522fd72f2', 'c703cab4-4562-496e-9243-fd6bd05d9a80', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Porque ela faz a gente questionar a verdade e perder a confiança em Deus, abrindo espaço para decisões erradas.', '2026-04-22 16:17:10.470994+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('4e501d7e-822c-4903-acb8-0d8d72cfa493', 'c703cab4-4562-496e-9243-fd6bd05d9a80', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Quando passo por dificuldades, não entendo o que está acontecendo ou quando sinto medo e insegurança.', '2026-04-22 16:17:10.470994+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('e2cf3f0a-1f44-46f5-a281-f4a4591c2aae', '528f1076-2f86-4c8f-ae7f-cb0a460e4f49', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Porque várias pessoas vão perdendo a fé em Deus até que se perguntam algumas perguntas como, será que Deus existe? Será que foi isso mesmo que ele disse?', '2026-04-22 17:57:05.186939+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('0fb13cab-3383-4cd0-b59c-1aba1e325f33', '528f1076-2f86-4c8f-ae7f-cb0a460e4f49', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'As vezes é difícil quando está tudo "dando errado" na nossa vida .', '2026-04-22 17:57:05.186939+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('2841e771-c86e-44e7-9da7-2b5cb084c216', '2f773751-38c2-45a1-8ee0-f5b856092730', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Porque deixamos de confiar em Deus ', '2026-04-22 18:47:09.622947+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('e44b3673-dc4d-4dd7-a7eb-b420761ccfa1', '2f773751-38c2-45a1-8ee0-f5b856092730', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Quando perdemos o controle sobre algo e nos problemas da vida. ', '2026-04-22 18:47:09.622947+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('49de60bf-c404-4751-b677-c38ae3837559', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '2e26fe88-3337-4504-a083-c448326f0210', 0, 'Porque o pecado afeta nossa identidade e faz a gente acreditar que nossos erros nos definem. Muitas vezes a culpa e a lembrança do passado falam mais alto, e esquecemos que, em Cristo, podemos ser restaurados e ter uma nova identidade.', '2026-04-22 18:55:20.432737+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('7e37f96b-e9c1-41cf-9239-f8b325cf2800', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '2e26fe88-3337-4504-a083-c448326f0210', 1, 'Significa que, como está em 2 Coríntios 5:17, eu me torno uma nova criatura. As coisas antigas ficam para trás e começo uma nova vida em Cristo. Não sou mais definido pelos meus pecados, mas pelo que Deus diz sobre mim: perdoado, reconciliado e filho de Deus.', '2026-04-22 18:55:20.432737+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('d473f318-d52a-4eb1-b930-8510efb50c3d', '9289d1ce-a632-4cd7-930e-73023e549ec5', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Pois ela pode fazer você parar de confiar em Deus,assim sua fé se desfazendo', '2026-04-22 19:36:15.731558+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('98118647-dcfe-478e-bd2a-a767dc66a03c', '9289d1ce-a632-4cd7-930e-73023e549ec5', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Quando alguma coisa ruim acontece na sua vida,como a morte de alguém especial,ou um acidente', '2026-04-22 19:36:15.731558+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('234d5ffd-fd5e-4ad7-a304-1f07e88529f2', '1526dc8b-a92a-4a44-b358-b6a3083d0143', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Porque pede para Deus o que ele disse ', '2026-04-22 22:34:26.071113+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('e83335b5-d99e-43ae-8f34-5eae25a75d5b', '1526dc8b-a92a-4a44-b358-b6a3083d0143', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Nos momentos que estamos pecando o outro ', '2026-04-22 22:34:26.071113+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('396a1049-ba83-44dc-b3ed-05d9cb77eff4', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Por que é mais fácil ser atraído pelo mal do que fazer o bem.', '2026-04-22 23:08:31.945129+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('b4b4631c-f8b6-4c96-a2ef-081afdb82db4', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 1, 'Naqueles momentos que nada da certo e que você está muito enraivado.', '2026-04-22 23:08:31.945129+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('903f66d8-3dd2-45d6-bcf3-dcf4d3adf0be', '914b898d-24a3-46ad-a764-d2f24e5115d1', 'acd52f9f-c877-46b5-a897-1a1c1638781a', 0, 'Porque Jesus não desiste dos seus filhos ', '2026-04-22 23:17:19.993285+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
