INSERT INTO public.devotional_responses VALUES ('b2dd849a-237a-4014-9d1c-dd6860b119da', 'ba6442c9-bc68-4670-a14f-bc7f7225fb93', 'af440fb5-5112-4e54-bbb3-82812e917370', 0, 'Para os outros não acharem que ela é fraca e sente vergonha dos erros por isso tenta escondê-los ', '2026-04-24 16:42:55.890421+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('024ec261-798d-4240-add3-b67cb0fe42f9', 'ba6442c9-bc68-4670-a14f-bc7f7225fb93', 'af440fb5-5112-4e54-bbb3-82812e917370', 1, 'Deus nos dá mais confiança  e não nos deixa sentir sozinho ', '2026-04-24 16:42:55.890421+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('a3496efb-dbb0-44fd-9b91-8c27167c10be', 'c703cab4-4562-496e-9243-fd6bd05d9a80', 'af440fb5-5112-4e54-bbb3-82812e917370', 0, 'As pessoas escondem suas falhas porque sentem vergonha, medo de serem julgadas ou rejeitadas', '2026-04-24 18:20:33.717976+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
