INSERT INTO public.devotional_responses VALUES ('27e2e241-3210-4b3e-8cf4-c8bf920df051', '914b898d-24a3-46ad-a764-d2f24e5115d1', 'af440fb5-5112-4e54-bbb3-82812e917370', 1, 'Com confiança em perdão de Jesus ', '2026-04-24 23:23:37.111999+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('f84dc81b-8907-4773-96cf-aa4999fa1890', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', 'af440fb5-5112-4e54-bbb3-82812e917370', 0, 'As pessoas tentam esconder suas falhas porque sentem vergonha e insegurança, assim como Adão e Eva depois da queda. Antes eles viviam em liberdade, mas depois surgiu o medo, e isso faz a gente querer se esconder e não mostrar nossos erros.', '2026-04-25 00:31:20.016303+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('ecd9e1e3-3f5d-4726-a227-725dadc28054', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', 'af440fb5-5112-4e54-bbb3-82812e917370', 1, 'O evangelho muda isso porque mostra que Deus não nos abandona. Em Jesus, Ele oferece perdão e nova vida, então não precisamos nos esconder, mas podemos confiar que Ele nos aceita e nos ajuda a melhorar.', '2026-04-25 00:31:20.016303+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('b9a814d6-7dec-40b1-bd28-53acbaeb8d3f', '70a2c6f1-f740-4669-b8dc-29b38f04d9d9', '9bbdbde3-6e68-4147-9731-738b3c553c48', 0, 'É processual.', '2026-04-25 00:39:02.055095+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('e23d1c07-61ec-4253-a8f6-33bb628d4dcb', '70a2c6f1-f740-4669-b8dc-29b38f04d9d9', '9bbdbde3-6e68-4147-9731-738b3c553c48', 1, 'Pensamentos positivos. ', '2026-04-25 00:39:02.055095+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('07db05ed-14c6-4c2e-9224-1730d9114220', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', 'af440fb5-5112-4e54-bbb3-82812e917370', 0, 'Para não serem criticadas', '2026-04-25 00:48:39.112561+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('26b06e40-501e-4dd7-81e7-8a0f7530c462', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', 'af440fb5-5112-4e54-bbb3-82812e917370', 1, 'Ele nos ajuda a ter confiança não ter vergonha ser mais confiante e se sentir confortável ', '2026-04-25 00:48:39.112561+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('721e856a-2fa9-4854-8cd7-6b890e584f66', '4d062445-4744-4007-a2ac-d7c4743fc979', 'af440fb5-5112-4e54-bbb3-82812e917370', 0, 'Nós talentos', '2026-04-25 00:48:55.514889+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('6a7e6760-1c9a-4c5d-895c-e20ccc3d3b71', '4d062445-4744-4007-a2ac-d7c4743fc979', 'af440fb5-5112-4e54-bbb3-82812e917370', 1, 'Enfrentando
INSERT INTO public.devotional_responses VALUES ('2cff80c1-5d2d-40d4-9e0c-ee5d46f4edc3', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'af440fb5-5112-4e54-bbb3-82812e917370', 0, 'Por que elas sentem vergonha por sua falha, e não querem confessar o seu erro ou falha, e por isso elas escondem para não afetar sua reputação.', '2026-04-25 00:49:29.91335+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('dee177cf-45e8-4bf4-8564-527d8c012c67', 'f753b131-e334-4645-95d6-dd7f3f1193fc', 'af440fb5-5112-4e54-bbb3-82812e917370', 1, 'Podemos ter como certeza que Deus não nos abandona, não nos rejeita mas sempre oferece perdão a nossa vida.', '2026-04-25 00:49:29.91335+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
