INSERT INTO public.devotional_responses VALUES ('7a07fac8-a29b-4722-9642-e16033d91d83', '32a9f112-1192-4b2a-918f-c2895a76ade3', '6cb1c7b2-9946-4bb3-bda2-d4715e2ce7ad', 0, 'Pois isso piora e dificulta a vida delas', '2026-04-27 18:56:07.663282+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
