INSERT INTO public.devotional_responses VALUES ('4ffe50d7-70ce-4788-9119-b42319abe65d', '9289d1ce-a632-4cd7-930e-73023e549ec5', '6cb1c7b2-9946-4bb3-bda2-d4715e2ce7ad', 0, 'Com medo de se pecar,ter traído Deus', '2026-04-27 21:38:45.593684+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
