INSERT INTO public.devotional_responses VALUES ('3bef2e68-96a5-4982-b7a4-62350f973100', '528f1076-2f86-4c8f-ae7f-cb0a460e4f49', '6cb1c7b2-9946-4bb3-bda2-d4715e2ce7ad', 0, 'Algumas pessoas se afastam pois ficam dúvidas sobre Ele, se Ele existe mesmo e se é mesmo verdade as coisas que nos contam ', '2026-04-27 22:03:31.587842+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
