INSERT INTO public.devotional_responses VALUES ('618f3473-7394-4dd1-b815-43d1d0ec5128', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '6cb1c7b2-9946-4bb3-bda2-d4715e2ce7ad', 0, 'Porque, quando erram, sentem medo ou vergonha. Assim como Adão e Eva se esconderam, muitas pessoas se afastam achando que Deus não vai aceitá-las por causa do pecado.', '2026-04-27 22:20:52.160615+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
