INSERT INTO public.devotional_responses VALUES ('407488ac-a917-4f87-b02e-e4518bc724f1', 'ba6442c9-bc68-4670-a14f-bc7f7225fb93', '4b1ef781-a51f-482f-bd43-e127c8c29a97', 1, 'Não a outra maior que ele ', '2026-04-29 23:11:50.483926+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('40fbc991-7da8-4684-b70a-5a0a5b36dbc0', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '4b1ef781-a51f-482f-bd43-e127c8c29a97', 0, 'Por que o coração de Deus é muito bom, pois ele perdoa muitos pecados e essa promessa mostra o quanto Deus pode amar agente.', '2026-04-29 23:21:58.329074+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
