INSERT INTO public.devotional_responses VALUES ('ea7f9118-3fb3-49fd-8153-18ec273a6939', 'c703cab4-4562-496e-9243-fd6bd05d9a80', 'c586266a-7578-41d1-8d0c-ee74b50a6b82', 0, 'Porque querem ser aceitas, evitar críticas e esconder suas falhas por medo ou vergonha.', '2026-05-02 14:35:28.091407+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
