INSERT INTO public.devotional_responses VALUES ('e025b9c6-c313-4cd3-b639-f6a242d3e114', '66b31cf2-7782-4253-98ea-3b6d631703a4', '663eb047-ecdf-46a7-a9a7-56bde90286b5', 0, 'N cumprir o desejo da carne ', '2026-05-02 15:59:43.472691+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
