INSERT INTO public.devotional_responses VALUES ('763db56e-85c5-4739-a7bb-7dd7d3289a28', 'af8a49dd-780a-419f-b967-a9c9e4b5837c', '663eb047-ecdf-46a7-a9a7-56bde90286b5', 0, 'Andando pelo espírito não precisarás cumprir o desejo da carne', '2026-05-02 19:22:38.578669+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
