INSERT INTO public.devotional_responses VALUES ('28cc4751-c44c-410e-936a-f1218433917a', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 0, 'As pessoas normalmente procuram seu valor na opinião dos outros, na aparência, nas conquistas, nas notas e na popularidade.', '2026-05-11 21:04:23.896765+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
