INSERT INTO public.devotional_responses VALUES ('1c182e49-8f94-4926-bbfc-74f08274deae', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 2, 'Saber que sou filho de Deus muda minha forma de viver, porque entendo que já sou amado e aceito por Ele, sem precisar provar meu valor para os outros.', '2026-05-11 21:04:23.896765+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
