INSERT INTO public.devotional_responses VALUES ('3d013d00-8773-4033-894d-5e29019ad8e7', '4d062445-4744-4007-a2ac-d7c4743fc979', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 2, 'Muda que eu tenho o valor do criador ', '2026-05-11 21:09:55.347775+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
