INSERT INTO public.devotional_responses VALUES ('2957e4b2-ae15-4432-965d-87e5b296b7bb', '1526dc8b-a92a-4a44-b358-b6a3083d0143', '5e859f9e-3016-4482-96fd-1cae2e76f966', 0, 'Eramos e se afastamos de Deus mas também e viver afastados de deus ', '2026-05-12 21:41:21.190273+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('9f50c9fc-16aa-44ed-bf35-4b7da55ea4be', '1526dc8b-a92a-4a44-b358-b6a3083d0143', '5e859f9e-3016-4482-96fd-1cae2e76f966', 1, 'O pecado afasta nós não só na atitude mas também na nossa identidade ', '2026-05-12 21:41:21.190273+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
