INSERT INTO public.devotional_responses VALUES ('ce7a3ea1-3b87-4956-a1b0-04869d64a812', '2f773751-38c2-45a1-8ee0-f5b856092730', '22ba4407-0c53-4c71-b29d-e341d3c904e9', 2, 'ok', '2026-05-12 22:49:28.663708+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('dedc52c0-f842-49ec-aa98-6f26a15c5f7e', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '5e859f9e-3016-4482-96fd-1cae2e76f966', 0, 'Pecado não é só fazer coisas erradas, mas também viver longe de Deus e tentar viver sem Ele.', '2026-05-12 22:51:38.723663+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('18dc655e-d7a2-4ee9-925b-93adb84de682', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '5e859f9e-3016-4482-96fd-1cae2e76f966', 1, 'O pecado afeta a vida das pessoas trazendo medo, culpa, comparação e orgulho, bagunçando o coração e a vida.', '2026-05-12 22:51:38.723663+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('67282aff-37a3-4c70-ab2f-be8dad43d345', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '5e859f9e-3016-4482-96fd-1cae2e76f966', 2, 'É importante entender que todos pecaram porque assim reconhecemos que precisamos de Deus e da salvação em Jesus.', '2026-05-12 22:51:38.723663+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('09087b10-4d64-4c62-8fed-c33ecf9fdcf8', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '5e859f9e-3016-4482-96fd-1cae2e76f966', 0, 'Agente tentar fazer algo que sabe que não consegue para se exibir para os outros, pegar e fazer aquilo mais não assumir que fez.', '2026-05-12 23:02:17.611215+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('cb253b14-1365-4380-a149-c171975f7698', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '5e859f9e-3016-4482-96fd-1cae2e76f966', 1, 'Fazendo com que as pessoas se tornam pecadores, e isso acaba afastando-se de Deus.', '2026-05-12 23:02:17.611215+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('4e3ecfef-3615-4a7c-ba1f-01ab5b22eabc', 'f753b131-e334-4645-95d6-dd7f3f1193fc', '5e859f9e-3016-4482-96fd-1cae2e76f966', 2, 'Porque se agente não intender, e achar isso certo, não vai para o céu e Deus não nos perdoa.', '2026-05-12 23:02:17.611215+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('aa414ac4-c01d-40af-8216-59d47f0fde80', 'aa7cfdb6-13b7-4988-8922-86de735eeab2', '5e859f9e-3016-4482-96fd-1cae2e76f966', 0, 'É viver longe de Deus sempre escolhendo o nosso próprio caminho ', '2026-05-13 00:01:29.636505+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('8cea01a1-5a11-4fa8-b537-1a5c245213f7', 'aa7cfdb6-13b7-4988-8922-86de735eeab2', '5e859f9e-3016-4482-96fd-1cae2e76f966', 1, 'Ele bagunça nossa identidade traz culpa medo etc...', '2026-05-13 00:01:29.636505+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('3e024399-08a9-45fe-9097-bb1d9e4bcd7d', 'aa7cfdb6-13b7-4988-8922-86de735eeab2', '5e859f9e-3016-4482-96fd-1cae2e76f966', 2, 'Por que mostra que precisamos de um salvador: Jesus', '2026-05-13 00:01:29.636505+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('8edcf0c5-d857-4715-b8d9-a72117ffc02c', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '5e859f9e-3016-4482-96fd-1cae2e76f966', 0, 'Fazer o errado para Deus, magoar ele e faz nos afastar dele', '2026-05-13 01:29:01.451221+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.devotional_responses VALUES ('455f1e46-57ca-4ef3-b282-bba7db1492b7', '0051fdc1-7e85-4d26-b24c-a12d2dc41781', '5e859f9e-3016-4482-96fd-1cae2e76f966', 1, 'Ele nos afasta de Deus ', '2026-05-13 01:29:01.451221+00', '2026-05-13 17:58:22.190502+00', '02f08580-80e5-4f57-8a2e-1b078d337278');
