INSERT INTO public.lesson_responses VALUES ('e977cceb-11ca-4efd-9f25-764e161b3164', '2f773751-38c2-45a1-8ee0-f5b856092730', 'afb407be-cc20-47bf-8714-d8a4a19d83cc', 'q1', 'POrque duvidamos que Deus é bom. Duvidamos que ele nos ama.', '2026-05-02 13:52:50.632852+00', '2026-05-13 12:53:51.627337+00', NULL, NULL, '02f08580-80e5-4f57-8a2e-1b078d337278');
