INSERT INTO public.lesson_responses VALUES ('bac60ea8-9926-40df-8afc-31884cbc6d6c', 'c323dbd0-4856-47eb-82ca-6e2c3bc7917a', '3a71d37e-b366-41ca-b6ae-c8fc7f77b522', 'q2', 'O que mais me chamou atenção é que nossa identidade vem de Deus, não do que fazemos ou do que os outros pensam ', '2026-05-02 02:24:48.150321+00', '2026-05-13 12:53:51.627337+00', NULL, NULL, '02f08580-80e5-4f57-8a2e-1b078d337278');
