INSERT INTO public.lesson_responses VALUES ('f315186b-d646-49d6-b98c-d3794b1e2e30', '2dcc9a0e-accc-42df-8c78-5577fc2669db', '3a71d37e-b366-41ca-b6ae-c8fc7f77b522', 'prayer', 'Obrigada senhor por tudo que você me deu e abençoe a todos que são verdadeiros e me amam , amém ', '2026-05-11 16:24:56.450601+00', '2026-05-13 12:53:51.627337+00', NULL, NULL, '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.lesson_responses VALUES ('3b566897-5d5b-4401-b529-9165bad42f31', '528f1076-2f86-4c8f-ae7f-cb0a460e4f49', '3a71d37e-b366-41ca-b6ae-c8fc7f77b522', 'q4', 'Provar para as pessoas que sou filha de Deus e fui criada a imagem d''Ele', '2026-05-11 20:49:19.586131+00', '2026-05-13 12:53:51.627337+00', NULL, NULL, '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.lesson_responses VALUES ('dcea1c7a-6f8b-4610-88a4-78bf6d5fdaf8', '528f1076-2f86-4c8f-ae7f-cb0a460e4f49', '3a71d37e-b366-41ca-b6ae-c8fc7f77b522', 'prayer', 'Senhor Deus obrigada por mais um dia maravilhoso, por essa semana abençoada e por mais um dia de vida, nos proteja de todo o mal, e que eu consiga realizar meu sonhos ! Mas que seja feita a tua vontade, amo você. Amém!', '2026-05-11 20:50:57.521941+00', '2026-05-13 12:53:51.627337+00', NULL, NULL, '02f08580-80e5-4f57-8a2e-1b078d337278');
INSERT INTO public.lesson_responses VALUES ('244d2041-1490-44f3-9fff-d6883c302df6', '528f1076-2f86-4c8f-ae7f-cb0a460e4f49', '3a71d37e-b366-41ca-b6ae-c8fc7f77b522', 'practice', 'Sou feita a imagem dele, ele me criou desse jeito, e não devo me comparar com os outros porque quem me fez assim foi Deus.', '2026-05-11 20:50:53.613025+00', '2026-05-13 12:53:51.627337+00', NULL, NULL, '02f08580-80e5-4f57-8a2e-1b078d337278');
